/**
 * Kalkulatzen du elementuaren offseta, 7 esalditik behera dituen txantiloi bat.
 * @param {Element} element - Elementua, bere offseta kalkulatzeko.
 * @returns {number} Elementuaren offseta, 7 esalditik behera dituen txantiloi bat.
 */
function calculateOffset(element) {
  let offset = 0;
  let parent = element.parentNode;

  // Offseta kalkulatzeko, guraso elementu guztien offseta gehitu behar da
  while (parent !== null) {
    offset += parent.offsetTop;
    parent = parent.parentNode;
  }

  return offset;
}
